float4 frag(UPEInput i)
{
    float life = 1.0 - i.color.a;
    float e = saturate((life - _ErodeStart) / max(1.0 - _ErodeStart, 0.001));
    float2 uv = lerp(i.uv, i.uv.yx, _SwapUV);
    float x = lerp(uv.x, 1.0 - uv.x, _FlipX);
    float y = uv.y - 0.5;

    // --- damla biçimli çizgi: baş x≈0.8'de yuvarlak, kuyruk x=0'a sivrilir ---
    float xs = saturate(x / 0.8);
    float hx = saturate((x - 0.8) / 0.18);
    float bodyW = 0.36 * pow(xs, 0.8);
    float capW = 0.36 * sqrt(saturate(1.0 - hx * hx));
    float hw = lerp(bodyW, capW, step(0.8, x));
    float nl = vnoise(float2(x * 4.0, 2.7));
    hw *= 0.88 + 0.24 * nl;
    float n2 = vnoise(float2(y * _Fiber, x * 5.0));
    float dEdge = hw - abs(y);
    float aStreak = AASTEP(0.0, dEdge);
    aStreak *= AASTEP((1.0 - x) * _Dry - 0.2, n2);
    aStreak *= AASTEP(e * 1.05, x * 0.8 + n2 * 0.2);
    float inkS = 1.0 - AASTEP(hw * _InkEdge, dEdge);
    float coreS = AASTEP(hw * 0.5, dEdge) * smoothstep(0.4, 0.75, x);

    // --- leke: kenarı loblu, içten delinerek erir ---
    float2 q = (i.uv - 0.5) * 2.0;
    float r = length(q);
    float2 dir = q / max(r, 0.0001);
    float lobe = vnoise(dir * 2.6 + float2(3.1, 7.7)) * 0.6 + vnoise(dir * 6.0 + float2(1.3, 2.9)) * 0.4;
    float R = (0.55 + 0.32 * lobe) * (1.0 - e * 0.6);
    float dS = R - r;
    float aSplat = AASTEP(0.0, dS);
    float holes = vnoise(q * 5.0 + float2(9.0, 4.0));
    aSplat *= AASTEP(e * 1.1 - 0.05, holes * 0.6 + 0.4 * (1.0 - r));
    float inkP = 1.0 - AASTEP(R * _InkEdge * 0.6, dS);
    float coreP = AASTEP(R * 0.6, dS);

    float a = lerp(aStreak, aSplat, _Splat);
    float ink = lerp(inkS, inkP, _Splat);
    float core = lerp(coreS, coreP, _Splat) * _CoreAmount;
    float3 c = i.color.rgb;
    c = lerp(c, _CoreColor.rgb, core);
    c = lerp(c, _InkColor.rgb, ink);
    return float4(c, a);
}
